        internal void ApplyCompletedParticipantCounts(int configured,int completed){if(configured!=completed||configured<1||configured>4)throw new ArgumentOutOfRangeException("configured/completed");for(int n=0;n<pairs.Length;n++)if(pairs[n][0]==configured&&pairs[n][1]==completed){counts.SelectedIndex=n;Pending();return;}throw new InvalidDataException("Completed participant count has no study choice.");}
        static Label Caption(string text){return new Label{Text=text,AutoSize=true,Margin=new Padding(5,7,3,3)};}
        static void Combo(ComboBox box,string name,int width){box.Name=name;box.DropDownStyle=ComboBoxStyle.DropDownList;box.Width=width;box.ForeColor=SystemColors.WindowText;box.BackColor=SystemColors.Window;}
        static Button Button(string name,string text){return new Button{Name=name,Text=text,AutoSize=true,Padding=new Padding(4),UseVisualStyleBackColor=true,ForeColor=SystemColors.ControlText,BackColor=SystemColors.Control};}
        void Pending()
        {
            if(StateSnapshot==null||IsDisposed||Disposing)return;var p=pairs[counts.SelectedIndex];bool same=StateSnapshot.ProducerCount==p[0]&&StateSnapshot.ConsumerCount==p[1]&&StateSnapshot.InitialSeed==(uint)seed.Value&&StateSnapshot.MapProfile==world.SelectedIndex-1;
            if(world.SelectedIndex==0)same=same&&StateSnapshot.InitialClock==(uint)(int)clockBase.SelectedItem&&StateSnapshot.ReserveFirstFleet==reserve.Checked&&StateSnapshot.InitialCounter==(counter.SelectedIndex==0?1u:uint.MaxValue);
            pending.Text=same?"Controls match the applied copy.":"Selection pending. Load applies these controls; Reset keeps the applied setup.";
        }
        void LoadCopy(bool reset)
        {
            if(IsDisposed||Disposing)return;
            try
            {
                if(reset&&StateSnapshot!=null)StateSnapshot=StateSnapshot.ResetCopy();
                else
                {
                    var p=pairs[counts.SelectedIndex];
                    var loaded=world.SelectedIndex==0
                        ?PracticeGeneratedReinforcements.Create(tables,p[0],p[1],(uint)seed.Value,(uint)(int)clockBase.SelectedItem,reserve.Checked,counter.SelectedIndex==0?1u:uint.MaxValue)
                        :PracticeGeneratedReinforcements.CreateMapped(tables,programs,File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(programs),"Assets","Graphics","BSSB202.SCN")),p[0],p[1],(uint)seed.Value,world.SelectedIndex-1);
                    StateSnapshot=loaded;
                }
                Sync();
            }
            catch(ArgumentException ex){pending.Text=ex.Message;}
            catch(IOException ex){pending.Text=ex.Message;}
            catch(NotSupportedException ex){pending.Text=ex.Message;}
        }
        void Advance(int action){if(IsDisposed||Disposing)return;try{var current=StateSnapshot;StateSnapshot=action==0?current.AtNextDeadline():action==1?current.JustAfterNextDeadline():action==2?current.RepeatClock():action==3?current.JumpPastRemaining():current.FinishInDeadlineOrder();Sync();}catch(InvalidOperationException ex){pending.Text=ex.Message;}catch(InvalidDataException ex){pending.Text=ex.Message;}}
        void Sync()
        {
            var s=StateSnapshot;summary.Text=string.Format("Applied producer {0} / consumer {1} · seed {2} · base {3} ms · reserved slot 0: {4}\r\nClock: {5} ms   |   Next: {6}   |   Pending: {7}   |   Visits: {8}/{9}\r\nCreated: {10} fleets / {11} units   |   Last refresh requests: {12}   |   RNG: {13}",s.ProducerCount,s.ConsumerCount,s.InitialSeed,s.InitialClock,s.ReserveFirstFleet?"yes":"no",s.Clock,s.NextDeadline.HasValue?s.NextDeadline.Value+" ms":"none in consumer",s.PendingEvents,s.Visits,PracticeGeneratedReinforcements.MaximumVisits,s.CreatedFleetCount,s.CreatedUnitCount,s.RefreshRequests,s.RandomState);
            summary.Text+="\r\nBasis: "+s.BasisDescription+" · existing "+s.ExistingFleetCount+" fleets / "+s.ExistingUnitCount+" units · initial RNG "+s.InitialRandomState;
            schedule.Rows.Clear();for(int group=0;group<4;group++)for(int slot=0;slot<4;slot++){int deadline=s.DeadlineAt(group,slot),payload=s.PayloadAt(group,slot);string status=group>=s.ProducerCount?"Untouched":group>=s.ConsumerCount?"Outside consumer":deadline==-1?"Consumed":unchecked((int)s.Clock)==deadline?"Equality held":"Waiting";int row=schedule.Rows.Add(group,slot,deadline==-1?"-1":deadline.ToString(),group>=s.ProducerCount?"retained":payload.ToString(),status);if(group>=s.ConsumerCount)schedule.Rows[row].DefaultCellStyle.ForeColor=Color.SlateGray;schedule.Rows[row].Cells[3].ToolTipText="Raw supplied/source payload: "+payload;}
            object old=fleetChoice.SelectedItem;syncing=true;fleetChoice.Items.Clear();foreach(int fleet in s.FleetIds())fleetChoice.Items.Add(fleet);fleetChoice.Enabled=fleetChoice.Items.Count>0;if(s.LastCreated.Count>0)fleetChoice.SelectedItem=s.LastCreated[s.LastCreated.Count-1].Fleet;else if(old!=null&&fleetChoice.Items.Contains(old))fleetChoice.SelectedItem=old;else if(fleetChoice.Items.Count>0)fleetChoice.SelectedIndex=0;syncing=false;
            bool next=s.CanVisit&&s.NextDeadline.HasValue;equality.Enabled=next;after.Enabled=next;jump.Enabled=next;finish.Enabled=next;repeat.Enabled=s.CanVisit;Pending();Inspect();canvas.Invalidate();
        }
        void Inspect()
        {
            if(StateSnapshot==null||IsDisposed||Disposing)return;var s=StateSnapshot;var text=new StringBuilder();text.Append("Last visit creations (source group/slot order):\r\n");if(s.LastCreated.Count==0)text.Append("  None. Equality and repeated-clock visits do not create fleets.\r\n");foreach(var made in s.LastCreated)text.AppendFormat("  Fleet {0}: group {1}, slot {2}, template {3}, world {4},{5}, units {6}\r\n",made.Fleet,made.Group,made.Slot,made.Template,made.World.X,made.World.Y,made.Units.Count);
            if(fleetChoice.SelectedItem!=null){int fleet=(int)fleetChoice.SelectedItem;var ships=s.CopyShipPool();var fleets=s.CopyFleetPool();int at=fleet*492;text.AppendFormat("\r\nSelected fleet {0}: group {1}, world {2},{3}, display counter {4}, owner counter now {5}\r\n",fleet,BitConverter.ToInt16(fleets,at+6),BitConverter.ToInt16(fleets,at+12),BitConverter.ToInt16(fleets,at+14),fleets[at+484],s.OwnerCounter(BitConverter.ToInt16(fleets,at+6)));text.Append("Unit   Type   Length   Local X,Y\r\n");foreach(int unit in s.UnitIds(fleet)){int p=unit*268,type=BitConverter.ToInt32(ships,p);text.AppendFormat("{0,4}   {1,4}   {2,6}   {3},{4}\r\n",unit,type,BitConverter.ToInt16(ships,p+14),BitConverter.ToInt16(ships,p+8),BitConverter.ToInt16(ships,p+10));if(type==15){text.Append("  Type 15 stock[0..34]: ");for(int n=0;n<35;n++){if(n>0)text.Append(",");text.Append(BitConverter.ToInt16(ships,p+196+n*2));}text.Append("\r\n");}}text.Append("Local grid (rows X, columns Y; 2 = occupied):\r\n");for(int x=0;x<10;x++){for(int y=0;y<10;y++)text.Append(BitConverter.ToInt32(fleets,at+64+(x*10+y)*4)==2?'2':'.');text.Append("\r\n");}}
            text.Append(s.UsesOccupiedMap?"\r\nOccupied-map composition matched 916 original states in 64 supplied histories.\r\nBay members and units before kinds 22/23 remain reserved; gray squares are existing fleets.\r\nBank 5/global mode 5 is deliberately supplied on BSSB202 copies; no natural transition is claimed.":"\r\nEmpty-world composition matched 1,380 original states in 96 supplied histories.");text.Append("\r\nExplicit comparison counts and clock visits; this is not a complete running Practice mission.");details.Text=text.ToString();
        }
        void Draw(object sender,PaintEventArgs e)
        {
            var g=e.Graphics;g.Clear(BackColor);if(StateSnapshot==null)return;g.SmoothingMode=SmoothingMode.AntiAlias;float size=Math.Min(canvas.ClientSize.Width-70,canvas.ClientSize.Height-65);if(size<=0)return;float left=45,top=28,scale=size/630;using(var grid=new Pen(Color.FromArgb(34,57,73)))using(var brush=new SolidBrush(Color.LightSteelBlue)){for(int n=0;n<=7;n++){int value=n==7?630:n*100;float at=value*scale;g.DrawLine(grid,left+at,top,left+at,top+size);g.DrawLine(grid,left,top+at,left+size,top+at);if(n!=6)g.DrawString(value.ToString(),Font,brush,left+at-8,top-23);g.DrawString(value.ToString(),Font,brush,left-36,top+at-7);}}
            if(!StateSnapshot.UsesOccupiedMap){using(var fixture=new Pen(Color.Turquoise,2))g.DrawRectangle(fixture,left-5,top+250*scale-5,10,10);}else{var existing=StateSnapshot.CopyExistingFleetPool();using(var pen=new Pen(Color.SlateGray,1.5f))for(int fleet=0;fleet<250;fleet++){int at=fleet*492;if(BitConverter.ToInt32(existing,at)==0)continue;float x=left+BitConverter.ToInt16(existing,at+12)*scale,y=top+BitConverter.ToInt16(existing,at+14)*scale;g.DrawRectangle(pen,x-3,y-3,6,6);}}var pool=StateSnapshot.CopyFleetPool();Color[] colors={Color.CornflowerBlue,Color.Orange,Color.MediumSeaGreen,Color.Violet};foreach(int fleet in StateSnapshot.FleetIds()){int at=fleet*492,group=BitConverter.ToInt16(pool,at+6);float x=left+BitConverter.ToInt16(pool,at+12)*scale,y=top+BitConverter.ToInt16(pool,at+14)*scale;bool selected=fleetChoice.SelectedItem!=null&&(int)fleetChoice.SelectedItem==fleet;using(var pen=new Pen(selected?Color.Gold:colors[group],selected?3:2))g.DrawEllipse(pen,x-5,y-5,10,10);if(selected)using(var brush=new SolidBrush(Color.Gold))g.DrawString("Fleet "+fleet,Font,brush,Math.Min(left+size-60,x+9),Math.Max(top+4,y-17));}
        }
        internal bool StudyKey(Keys key,bool down){if(key!=Keys.Enter&&key!=Keys.Escape)return false;if(!down){held.Remove(key);return true;}if(!held.Add(key))return true;if(key==Keys.Escape)Close();else LoadCopy(false);return true;}
        protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(StudyKey(keyData&Keys.KeyCode,true))return true;return base.ProcessCmdKey(ref message,keyData);}
        protected override void OnKeyUp(KeyEventArgs e){if(StudyKey(e.KeyCode,false))e.Handled=true;base.OnKeyUp(e);}
        protected override void OnActivated(EventArgs e){base.OnActivated(e);foreach(Keys key in new[]{Keys.Enter,Keys.Escape})if(GetAsyncKeyState((int)key)<0)held.Add(key);else held.Remove(key);}
        protected override void Dispose(bool disposing){if(disposing)mono.Dispose();base.Dispose(disposing);}
    }
